<?php use Aibid\Http\View as V; ?>
<div class="page-heading"><div><span class="eyebrow">DERECHOS Y VIGENCIAS</span><h1>Licencias</h1><p>Consulta lo que cada cliente tiene autorizado.</p></div><?php if ($actor->canWrite()): ?><a href="/admin/licenses/new" class="btn btn-primary">＋ Emitir licencia</a><?php endif; ?></div>
<section class="panel"><form method="get" class="filter-bar flex-wrap"><div class="search-field"><label for="q" class="visually-hidden">Buscar licencia</label><input class="form-control" id="q" name="q" placeholder="Cliente o identificador de licencia…" value="<?= V::escape($filters['q']) ?>"></div><label for="product_id" class="visually-hidden">Producto</label><select id="product_id" name="product_id" class="form-select filter-select"><option value="">Todos los productos</option><?php foreach ($products as $product): ?><option value="<?= V::escape($product['product_id']) ?>" <?= $filters['product_id']===$product['product_id']?'selected':'' ?>><?= V::escape($product['display_name']) ?></option><?php endforeach; ?></select><label for="status" class="visually-hidden">Estado comercial</label><select name="status" id="status" class="form-select filter-select"><option value="">Todos los estados</option><option value="issued" <?= $filters['status']==='issued'?'selected':'' ?>>Emitidas</option><option value="revoked" <?= $filters['status']==='revoked'?'selected':'' ?>>Revocadas</option></select><label for="type" class="visually-hidden">Modalidad</label><select name="type" id="type" class="form-select filter-select"><option value="">Todas las modalidades</option><option value="perpetual" <?= $filters['type']==='perpetual'?'selected':'' ?>>Perpetua</option><option value="subscription" <?= $filters['type']==='subscription'?'selected':'' ?>>Suscripción</option></select><label for="expiry" class="visually-hidden">Vencimiento</label><select name="expiry" id="expiry" class="form-select filter-select"><option value="">Cualquier vencimiento</option><option value="soon" <?= $filters['expiry']==='soon'?'selected':'' ?>>Próximos 30 días</option><option value="expired" <?= $filters['expiry']==='expired'?'selected':'' ?>>Fecha cumplida</option></select><button class="btn btn-outline-secondary">Filtrar</button></form>
<?php if (!$listing['rows']): ?><div class="empty-state"><div class="empty-symbol" aria-hidden="true">◇</div><h3>No hay licencias para mostrar</h3><p>Emite una licencia o ajusta los filtros.</p></div><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Cliente / producto</th><th>Modalidad</th><th>Estado comercial</th><th>Vencimiento</th><th></th></tr></thead><tbody><?php foreach ($listing['rows'] as $license): ?><tr><td><strong><?= V::escape($license['customer_name']) ?></strong><small class="cell-sub"><?= V::escape($license['product_name']) ?></small></td><td><?= $license['license_type']==='perpetual'?'Perpetua':'Suscripción' ?></td><td><span class="tag <?= $license['commercial_status']==='revoked'?'tag-red':'tag-green' ?>"><?= $license['commercial_status']==='revoked'?'Revocada':'Emitida' ?></span></td><td><?= $license['expires_at']===null?'Sin vencimiento':V::escape(V::date($license['expires_at'])) ?></td><td><a class="text-link" href="/admin/licenses/<?= V::escape($license['id_text']) ?>">Detalle →</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php require __DIR__.'/pagination.php'; ?></section>
